INSERT OR IGNORE INTO movies (id, title, category, poster, video_url, description, date) VALUES
('1', 'Cyberpunk 2077: Edge', 'D', 'https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/dQw4w9WgXcQ', 'เรื่องราวโลกอนาคตไซไฟสุดล้ำยุค เมื่อเทคโนโลยีครอบงำมนุษยชาติ การต่อสู้เพื่อความอยู่รอดจึงเริ่มต้นขึ้นในเงามืดของแสงนีออน', '2026-03-01'),
('2', 'The Last Action Hero', 'A', 'https://images.unsplash.com/photo-1536440136628-849c177e76a1?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/dQw4w9WgXcQ', 'ภาพยนตร์แอคชั่นฟอร์มยักษ์ ระเบิดภูเขาเผากระท่อม การไล่ล่าข้ามโลกที่เต็มไปด้วยฉากบู๊ระห่ำสะใจทุกวินาที', '2026-03-02'),
('3', 'Echoes of Silence', 'B', 'https://images.unsplash.com/photo-1485846234645-a62644f84728?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/dQw4w9WgXcQ', 'ภาพยนตร์ดราม่าสะเทือนอารมณ์ เจาะลึกความสัมพันธ์ของมนุษย์และความเงียบงันที่ซ่อนความลับอันเจ็บปวดไว้เบื้องหลัง', '2026-03-03'),
('4', 'Laugh Out Loud Comedy', 'C', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/dQw4w9WgXcQ', 'คอมเมดี้เบาสมองเสียงฮาครื้นคลัง ที่จะทำให้คุณหัวเราะจนกรามค้างไปกับมุกตลกสุดคาดเดาจากแก๊งเพื่อนซี้', '2026-03-04'),
('5', 'Nightmare Manor', 'E', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/dQw4w9WgXcQ', 'ภาพยนตร์สยองขวัญสั่นประสาท บ้านพักอาถรรพ์ที่ซ่อนวิญญาณและความสยดสยองรอผู้มาเยือนแบบไม่ทันตั้งตัว', '2026-03-05');
